// Lógica pura del bot "Afiliados - Publicar en Telegram". Testeable con
// `node workflows/src/validar_mensaje.js` por fuera de n8n. El Code node del
// workflow pega este archivo tal cual (funciones + bloque de invocación con
// $input/$env de abajo), mismo patrón que enviar_mensaje.json en lemut_n8n.
//
// Dos capas:
//   - procesarMensaje(): decide acceso (dueño/aprobado/solicitud de código/
//     comandos de admin) y delega a validarMensaje() cuando el remitente ya
//     tiene acceso. Devuelve 1 o 2 mensajes a mandar (solicitante + dueño).
//   - validarMensaje(): asume que el remitente YA tiene acceso; decide si
//     publica (foto + link válidos) o pide instrucciones.
const LIMITE_CAPTION = 1024; // límite real de Telegram para caption de foto (sendPhoto).
const LIMITE_TEXTO_CUPONES = 4096; // límite real de Telegram para sendMessage (anuncio de cupones).
// Dominios exactos, anclada (^...$) y probada token por token (ver extraerLink):
// evita que "evilmeli.la", "evilmercadolibre.com.mx" o un link ajeno con
// "meli.la" escondido en query string (otro.com/?u=meli.la/x) cuenten como
// link válido — sin anclar, la regex los matcheaba como substring.
const LINK_RE = /^(https?:\/\/)?(meli\.la\/\S+|(?:[\w-]+\.)*mercadolibre\.com\.mx\/\S*)$/i;

const CODIGO_VIGENCIA_MS = 10 * 60 * 1000; // 10 min.
const BLOQUEO_MS = 60 * 60 * 1000; // 1 h tras 3 intentos fallidos.
const MAX_INTENTOS = 3;

// Busca el link real dentro de un texto (caption de foto) probando cada
// palabra por separado (no el texto completo), para que el link pueda venir
// acompañado de texto propio ("Oferta <link>"). Devuelve el token exacto
// (lo necesita motor_caption.js para armar el caption nuevo con el link
// EXACTO como lo mandó el usuario, sin duplicar LINK_RE en otro Code node)
// y el texto restante sin el link.
function extraerLink(texto) {
  const tokens = (texto || '').split(/\s+/);
  const linkToken = tokens.find((token) => LINK_RE.test(token));
  if (!linkToken) return null;
  const textoSinLink = tokens.filter((t) => t !== linkToken).join(' ').trim();
  return { link: linkToken, textoSinLink };
}

// Un mensaje de texto (sin foto) "parece" un anuncio de cupones generales
// si menciona la palabra cupón/cupones o código — con o sin link: el link,
// si trae uno, casi siempre es de OTRA persona (su propio link de
// afiliado), nunca se publica (ver quitarLinks). La validación real de qué
// códigos son legítimos pasa después, en motor_cupones.js, contra el texto
// ya sin links.
const PARECE_CUPONES_RE = /cup[oó]n(es)?|c[oó]digo/i;

// Cualquier URL se quita del texto ANTES de mandarlo al LLM y antes de
// publicar el fallback — nunca se publica un link que no es nuestro.
// Genérica a propósito: no solo http(s):// ni solo meli.la/
// mercadolibre.com.mx, también cualquier dominio.tld(/ruta) SIN esquema
// (bit.ly/abc, t.me/canal, www.otro.com, x.com/algo...). El TLD final debe
// ser solo letras (2+) para no atrapar precios/decimales ("13,229.02").
const URL_GENERICA_RE = /https?:\/\/\S+|\b[\w-]+(?:\.[\w-]+)*\.[a-z]{2,}(?:\/\S*)?\b/gi;
function quitarLinks(texto) {
  return (texto || '')
    .replace(URL_GENERICA_RE, '')
    .replace(/[ \t]+$/gm, '') // espacios colgantes al final de línea, tras quitar el link.
    .replace(/\n{3,}/g, '\n\n') // no más de una línea en blanco seguida.
    .trim();
}

// Ya con acceso confirmado (dueño o aprobado): decide publicar (foto+link),
// cupones (texto sin foto + link, ver motor_cupones.js) o pedir instrucciones.
function validarMensaje(update) {
  const message = update.message;
  if (!message || !message.from) return { accion: 'ignorar' };

  const chatId = message.chat.id;
  const foto = message.photo;
  const tieneFoto = Array.isArray(foto) && foto.length > 0;

  if (tieneFoto) {
    const caption = message.caption || '';
    const extraido = extraerLink(caption);
    if (!extraido) {
      return {
        accion: 'responder',
        chatId,
        texto:
          'Manda una foto del producto con el link de Mercado Libre ' +
          '(meli.la/... o mercadolibre.com.mx) en el caption.',
      };
    }
    if (caption.length > LIMITE_CAPTION) {
      return {
        accion: 'responder',
        chatId,
        texto:
          `El caption tiene ${caption.length} caracteres y el límite de Telegram ` +
          `es ${LIMITE_CAPTION}. Acórtalo sin tocar el link y vuelve a mandarlo.`,
      };
    }
    const fileId = foto[foto.length - 1].file_id;
    return {
      accion: 'publicar',
      chatId,
      fileId,
      caption,
      link: extraido.link,
      textoUsuario: extraido.textoSinLink,
    };
  }

  // Sin foto: un mensaje de texto que PAREZCA anuncio de cupones generales
  // (ej. cupones bancarios del Buen Fin) va por motor_cupones.js, no por
  // motor_caption.js — con o sin link (si trae uno, se quita: casi siempre
  // es el link de afiliado de OTRA persona, nunca se publica). Cualquier
  // otro texto sin foto sigue el camino de siempre: instrucciones.
  const texto = message.text || '';
  if (!PARECE_CUPONES_RE.test(texto)) {
    return {
      accion: 'responder',
      chatId,
      texto:
        'Manda una foto del producto con el link de Mercado Libre ' +
        '(meli.la/... o mercadolibre.com.mx) en el caption.',
    };
  }

  const textoSinLinks = quitarLinks(texto);
  if (textoSinLinks.length > LIMITE_TEXTO_CUPONES) {
    return {
      accion: 'responder',
      chatId,
      texto:
        `El mensaje tiene ${textoSinLinks.length} caracteres y el límite de Telegram ` +
        `es ${LIMITE_TEXTO_CUPONES}. Acórtalo y vuelve a mandarlo.`,
    };
  }

  return { accion: 'cupones', chatId, texto: textoSinLinks };
}

// Código de 4 dígitos con crypto.randomInt. require() dentro de la función
// (no al nivel del módulo) para que funcione igual en node llano (self-check)
// y en el Code node de n8n, que necesita NODE_FUNCTION_ALLOW_BUILTIN=crypto
// (ver docker-compose.yml) para permitir este require().
function generarCodigo() {
  return String(require('crypto').randomInt(10000)).padStart(4, '0');
}

function nombreDe(from) {
  return [from.first_name, from.last_name].filter(Boolean).join(' ') || 'Alguien';
}

function usernameDe(from) {
  return from.username ? `@${from.username}` : 'sin username';
}

// Dueño: "/usuarios" lista base (.env) + aprobados. Devuelve null si el
// texto no es ese comando (para que el caller pruebe el siguiente).
function comandoUsuarios(text, allowedIds, estado) {
  if (text !== '/usuarios') return null;
  const base = allowedIds.length ? allowedIds.join(', ') : '(ninguno)';
  const aprobados = estado.aprobados.length ? estado.aprobados.join(', ') : '(ninguno)';
  return `Usuarios con acceso:\nBase (.env): ${base}\nAprobados: ${aprobados}`;
}

// Dueño: "/quitar <id>". Devuelve el id (string) o null si no es ese comando.
function comandoQuitarId(text) {
  const m = /^\/quitar\s+(\d+)\s*$/.exec(text);
  return m ? m[1] : null;
}

function quitarUsuario(estado, id) {
  const estaba = estado.aprobados.includes(id);
  estado.aprobados = estado.aprobados.filter((x) => x !== id);
  return estaba ? `Quitado: ${id}.` : `${id} no estaba en la lista de aprobados.`;
}

// Cuenta un fallo en una ventana propia de 1h por fromId, independiente del
// código/pendiente: así /start (código nuevo) no resetea el conteo y no se
// esquiva el bloqueo de 3 intentos dejando vencer el código.
function registrarFallo(estado, fromId, now) {
  if (!estado.fallos) estado.fallos = {}; // staticData persistido antes de este campo.
  let f = estado.fallos[fromId];
  if (!f || now - f.desde > BLOQUEO_MS) {
    f = { cuenta: 0, desde: now };
    estado.fallos[fromId] = f;
  }
  f.cuenta += 1;
  return f.cuenta;
}

// Remitente sin acceso: bloqueo, /start (pide código), intento de código, o
// ignora cualquier otro mensaje (no reenvía fotos/links ajenos al dueño).
function procesarAcceso(estado, update, ownerId, now) {
  const message = update.message;
  const fromId = String(message.from.id);
  const chatId = message.chat.id;
  const text = (message.text || '').trim();

  const bloqueadoHasta = estado.bloqueados[fromId];
  if (bloqueadoHasta && bloqueadoHasta > now) {
    return { resultados: [{ accion: 'ignorar' }], estado }; // bloqueado: silencio total.
  }

  if (/^\/start\b/.test(text)) {
    const pendienteVigente = estado.pendientes[fromId];
    // Ya hay una solicitud vigente: no generar código nuevo ni volver a
    // avisarle al dueño (si no, /start repetido resetea los intentos y
    // esquiva el bloqueo de 3 fallos, y le llena el chat al dueño de avisos).
    if (pendienteVigente && pendienteVigente.vence >= now) {
      return {
        resultados: [{ accion: 'responder', chatId, texto: 'Ya pediste acceso; pídele el código a Richer.' }],
        estado,
      };
    }

    const codigo = generarCodigo();
    estado.pendientes[fromId] = { codigo, vence: now + CODIGO_VIGENCIA_MS };
    return {
      resultados: [
        { accion: 'responder', chatId, texto: 'Pide el código de acceso a Richer y escríbelo aquí.' },
        {
          accion: 'responder',
          chatId: ownerId,
          texto:
            `Solicitud de acceso: ${nombreDe(message.from)} (${usernameDe(message.from)}, id ${fromId}). ` +
            'Código: ' + codigo + ' (vence en 10 min). Pásaselo solo si lo conoces.',
        },
      ],
      estado,
    };
  }

  if (/^\d{4}$/.test(text)) {
    const pendiente = estado.pendientes[fromId];
    if (!pendiente) return { resultados: [{ accion: 'ignorar' }], estado };

    if (pendiente.vence < now) {
      delete estado.pendientes[fromId];
      return {
        resultados: [{ accion: 'responder', chatId, texto: 'Tu código venció. Escribe /start para pedir uno nuevo.' }],
        estado,
      };
    }

    if (text === pendiente.codigo) {
      delete estado.pendientes[fromId];
      estado.aprobados.push(fromId);
      return {
        resultados: [
          { accion: 'responder', chatId, texto: 'Acceso concedido.' },
          { accion: 'responder', chatId: ownerId, texto: `${nombreDe(message.from)} ya tiene acceso.` },
        ],
        estado,
      };
    }

    const fallos = registrarFallo(estado, fromId, now);
    if (fallos >= MAX_INTENTOS) {
      delete estado.pendientes[fromId];
      delete estado.fallos[fromId];
      estado.bloqueados[fromId] = now + BLOQUEO_MS;
      return {
        resultados: [
          { accion: 'responder', chatId, texto: 'Código incorrecto 3 veces. Espera 1 hora e intenta otra vez con /start.' },
        ],
        estado,
      };
    }
    return {
      resultados: [
        { accion: 'responder', chatId, texto: `Código incorrecto. Te quedan ${MAX_INTENTOS - fallos} intento(s).` },
      ],
      estado,
    };
  }

  return { resultados: [{ accion: 'ignorar' }], estado };
}

// Punto de entrada único: decide acceso y delega. `estado` es el staticData
// global del workflow (aprobados/pendientes/bloqueados); se muta in-place y
// también se devuelve para persistirlo.
function procesarMensaje(estado, update, allowedIds, ownerId, now) {
  const message = update.message;
  if (!message || !message.from) return { resultados: [{ accion: 'ignorar' }], estado };

  const fromId = String(message.from.id);
  const chatId = message.chat.id;
  const text = (message.text || '').trim();
  const esDueño = Boolean(ownerId) && fromId === String(ownerId);
  const aprobado = allowedIds.includes(fromId) || estado.aprobados.includes(fromId);
  const permitido = esDueño || aprobado;

  if (esDueño) {
    const listaUsuarios = comandoUsuarios(text, allowedIds, estado);
    if (listaUsuarios !== null) {
      return { resultados: [{ accion: 'responder', chatId, texto: listaUsuarios }], estado };
    }
    const idAQuitar = comandoQuitarId(text);
    if (idAQuitar !== null) {
      const texto = quitarUsuario(estado, idAQuitar);
      return { resultados: [{ accion: 'responder', chatId, texto }], estado };
    }
  }

  if (permitido) {
    return { resultados: [validarMensaje(update)], estado };
  }

  return procesarAcceso(estado, update, ownerId, now);
}

function estadoVacio() {
  return { aprobados: [], pendientes: {}, bloqueados: {}, fallos: {} };
}

if (typeof module !== 'undefined') {
  module.exports = {
    validarMensaje,
    procesarMensaje,
    estadoVacio,
    extraerLink,
    quitarLinks,
    LIMITE_CAPTION,
    LIMITE_TEXTO_CUPONES,
    LINK_RE,
  };
}

// --- Bloque de invocación dentro de n8n (Code node) ---
// Fuera de n8n, $input/$env no existen y este bloque no corre (ver demo()).
if (typeof $input !== 'undefined') {
  // El Webhook node (no el Telegram Trigger) entrega el update de Telegram
  // dentro de `.body`; headers/query quedan en hermanos de ese campo.
  const update = $input.first().json.body;

  const staticData = $getWorkflowStaticData('global');

  // Dedupe por update_id: Telegram puede reentregar el mismo update (retries
  // de red); sin esto se publicaría/respondería dos veces. Se guarda en
  // staticData global del workflow (persiste entre ejecuciones).
  const vistos = staticData.updateIdsVistos || (staticData.updateIdsVistos = []);
  if (update.update_id !== undefined) {
    if (vistos.includes(update.update_id)) {
      return [{ json: { accion: 'ignorar' } }];
    }
    vistos.push(update.update_id);
    if (vistos.length > 200) vistos.splice(0, vistos.length - 200); // solo últimos ~200.
  }

  const allowedIds = ($env.TELEGRAM_ALLOWED_IDS || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
  const accesos = staticData.accesos || (staticData.accesos = estadoVacio());
  const resultado = procesarMensaje(accesos, update, allowedIds, $env.TELEGRAM_OWNER_ID, Date.now());
  return resultado.resultados.map((r) => ({ json: r }));
}

// --- Self-check mínimo (node workflows/src/validar_mensaje.js) ---
function demo() {
  const assert = require('assert');
  const ALLOWED = ['111111111'];
  const OWNER = '222222222';
  const base = (extra) => ({ message: { from: { id: 111111111 }, chat: { id: 111111111 }, ...extra } });
  const msj = (fromId, extra) => ({ message: { from: { id: fromId, first_name: 'Ana' }, chat: { id: fromId }, ...extra } });

  // --- foto + link, ya con acceso (vía procesarMensaje, flujo real) ---

  // Permitido, foto + link meli.la → publicar.
  let r = procesarMensaje(
    estadoVacio(),
    base({ photo: [{ file_id: 'a' }, { file_id: 'b' }], caption: 'Oferta https://meli.la/1NqM8Rd' }),
    ALLOWED,
    OWNER,
    1000,
  );
  assert.strictEqual(r.resultados.length, 1);
  assert.strictEqual(r.resultados[0].accion, 'publicar');
  assert.strictEqual(r.resultados[0].fileId, 'b'); // la de mayor resolución es la última.
  assert.strictEqual(r.resultados[0].link, 'https://meli.la/1NqM8Rd');
  assert.strictEqual(r.resultados[0].textoUsuario, 'Oferta'); // el link se excluye del texto del usuario.

  // Caption = solo el link (sin texto propio) → textoUsuario vacío.
  r = procesarMensaje(
    estadoVacio(),
    base({ photo: [{ file_id: 'a' }], caption: 'https://meli.la/1NqM8Rd' }),
    ALLOWED,
    OWNER,
    1000,
  );
  assert.strictEqual(r.resultados[0].textoUsuario, '');

  // Permitido, foto + link mercadolibre.com.mx sin https → publicar.
  r = procesarMensaje(
    estadoVacio(),
    base({ photo: [{ file_id: 'x' }], caption: 'Ver articulo.mercadolibre.com.mx/MLM-123' }),
    ALLOWED,
    OWNER,
    1000,
  );
  assert.strictEqual(r.resultados[0].accion, 'publicar');

  // Permitido, sin foto, menciona "cupones" y NO trae ningún link →
  // cupones generales de todos modos (es la ruta nueva para
  // motor_cupones.js; ya no depende de que venga un link).
  r = procesarMensaje(estadoVacio(), base({ text: 'Nuevos cupones del Buen Fin, usa el código ABC123' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'cupones');
  assert.strictEqual(r.resultados[0].texto, 'Nuevos cupones del Buen Fin, usa el código ABC123');
  assert.ok(!('link' in r.resultados[0])); // ya no se usa ningún link en esta plantilla.

  // Permitido, sin foto, menciona "cupones" y SÍ trae un link (casi
  // siempre de OTRA persona, su link de afiliado) → se quita el link antes
  // de seguir; el texto resultante no debe traer "meli.la" ni "http".
  r = procesarMensaje(estadoVacio(), base({ text: 'Cupones nuevos https://meli.la/1FBrqqE más info' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'cupones');
  assert.ok(!r.resultados[0].texto.toLowerCase().includes('meli.la'));
  assert.ok(!r.resultados[0].texto.toLowerCase().includes('http'));
  assert.strictEqual(r.resultados[0].texto, 'Cupones nuevos  más info'); // doble espacio donde estaba el link, sin rarezas.

  // Permitido, sin foto, cupones con un link SIN esquema (bit.ly/t.me/
  // dominio.com, no solo http(s):// o meli.la/mercadolibre.com.mx) → igual
  // se quita (bug ALTA reportado por el revisor: antes solo quitaba
  // http(s):// o los dos dominios de Mercado Libre).
  r = procesarMensaje(estadoVacio(), base({ text: 'Cupones: código ABC123, info en bit.ly/promo40' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'cupones');
  assert.ok(!r.resultados[0].texto.includes('bit.ly'));

  // Permitido, sin foto, sin la palabra cupón/código y sin foto →
  // instrucciones (no todo texto cuenta como cupones).
  r = procesarMensaje(estadoVacio(), base({ text: 'hola, alguna novedad?' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'responder');

  // Permitido, mensaje de cupones de más de 4096 caracteres → rechaza (no trunca).
  r = procesarMensaje(estadoVacio(), base({ text: 'Cupones: ' + 'a'.repeat(4090) }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'responder');
  assert.ok(r.resultados[0].texto.includes('4096'));

  // Permitido, con foto pero sin link → instrucciones.
  r = procesarMensaje(estadoVacio(), base({ photo: [{ file_id: 'a' }], caption: 'sin link aquí' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'responder');

  // Permitido, caption de más de 1024 → rechaza (no trunca).
  r = procesarMensaje(
    estadoVacio(),
    base({ photo: [{ file_id: 'a' }], caption: 'https://meli.la/x ' + 'a'.repeat(1030) }),
    ALLOWED,
    OWNER,
    1000,
  );
  assert.strictEqual(r.resultados[0].accion, 'responder');
  assert.ok(r.resultados[0].texto.includes('1024'));

  // Update sin message (ej. edited_message si algún día se suscribe) → ignorar.
  r = procesarMensaje(estadoVacio(), {}, ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'ignorar');

  // Dominio falsificado "evilmeli.la" (no es meli.la) → no cuenta como link.
  r = procesarMensaje(estadoVacio(), base({ photo: [{ file_id: 'a' }], caption: 'Oferta evilmeli.la/producto' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'responder');

  // Dominio falsificado "evilmercadolibre.com.mx" → no cuenta como link.
  r = procesarMensaje(estadoVacio(), base({ photo: [{ file_id: 'a' }], caption: 'Ver evilmercadolibre.com.mx/MLM-1' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'responder');

  // Link ajeno con "meli.la" escondido en query string → el host real es
  // otro.com, no cuenta como link válido.
  r = procesarMensaje(estadoVacio(), base({ photo: [{ file_id: 'a' }], caption: 'https://otro.com/?u=meli.la/x' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'responder');

  // --- alta de usuarios por código ---

  // No permitido + /start → pide código al solicitante y manda el código al dueño.
  let estado = estadoVacio();
  r = procesarMensaje(estado, msj(999, { text: '/start' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados.length, 2);
  assert.strictEqual(r.resultados[0].chatId, 999);
  assert.ok(r.resultados[0].texto.includes('código'));
  assert.strictEqual(r.resultados[1].chatId, OWNER);
  assert.ok(r.resultados[1].texto.includes('Ana') && r.resultados[1].texto.includes('999'));
  const codigoReal = estado.pendientes['999'].codigo;

  // No permitido + cualquier otra cosa (no /start, no código) → se ignora.
  r = procesarMensaje(estadoVacio(), msj(999, { text: 'hola' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'ignorar');

  // Código correcto antes de vencer → aprobado; avisa a ambos.
  r = procesarMensaje(estado, msj(999, { text: codigoReal }), ALLOWED, OWNER, 1500);
  assert.strictEqual(r.resultados.length, 2);
  assert.ok(r.resultados[0].texto.includes('concedido'));
  assert.strictEqual(r.resultados[1].chatId, OWNER);
  assert.ok(r.resultados[1].texto.includes('Ana'));
  assert.ok(estado.aprobados.includes('999'));

  // Código incorrecto (1er intento) → avisa, no bloquea.
  estado = estadoVacio();
  estado.pendientes['999'] = { codigo: '1234', vence: 100000 };
  r = procesarMensaje(estado, msj(999, { text: '0000' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'responder');
  assert.ok(r.resultados[0].texto.includes('incorrecto'));
  assert.strictEqual(estado.fallos['999'].cuenta, 1);

  // 3 fallos → bloqueado 1h; mientras dura, hasta el código correcto se ignora.
  estado = estadoVacio();
  estado.pendientes['999'] = { codigo: '1234', vence: 100000 };
  estado.fallos['999'] = { cuenta: 2, desde: 1000 };
  r = procesarMensaje(estado, msj(999, { text: '0000' }), ALLOWED, OWNER, 1000);
  assert.ok(r.resultados[0].texto.includes('1 hora'));
  assert.strictEqual(estado.bloqueados['999'], 1000 + 60 * 60 * 1000);
  r = procesarMensaje(estado, msj(999, { text: '1234' }), ALLOWED, OWNER, 1000 + 10);
  assert.strictEqual(r.resultados[0].accion, 'ignorar');

  // /start con una solicitud YA vigente → no genera código nuevo ni avisa
  // otra vez al dueño, y el contador de fallos (ventana propia, separado
  // del código) tampoco se resetea.
  estado = estadoVacio();
  estado.pendientes['999'] = { codigo: '1234', vence: 100000 };
  estado.fallos['999'] = { cuenta: 2, desde: 1000 };
  r = procesarMensaje(estado, msj(999, { text: '/start' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados.length, 1);
  assert.strictEqual(r.resultados[0].chatId, 999);
  assert.strictEqual(estado.pendientes['999'].codigo, '1234');
  assert.strictEqual(estado.fallos['999'].cuenta, 2);
  // Un fallo más SÍ debe bloquearlo (no se esquivó el contador).
  r = procesarMensaje(estado, msj(999, { text: '0000' }), ALLOWED, OWNER, 1000);
  assert.ok(r.resultados[0].texto.includes('1 hora'));
  assert.ok(estado.bloqueados['999']);

  // El mismo caso pero dejando VENCER el código entre fallo y fallo (no solo
  // "vigente"): hasta 20 ciclos de /start + 2 intentos incorrectos — el
  // contador de fallos tiene ventana propia de 1h, independiente del
  // código, así que bloquea aunque cada ciclo pida un código nuevo (antes,
  // /start reseteaba el conteo y el bloqueo se esquivaba indefinidamente).
  estado = estadoVacio();
  let momento = 1000;
  let ciclos = 0;
  for (; ciclos < 20 && !estado.bloqueados['999']; ciclos++) {
    if (estado.pendientes['999']) estado.pendientes['999'].vence = momento - 1; // forzar vencido
    procesarMensaje(estado, msj(999, { text: '/start' }), ALLOWED, OWNER, momento);
    for (let intento = 0; intento < 2 && estado.pendientes['999'] && !estado.bloqueados['999']; intento++) {
      const pend = estado.pendientes['999'];
      const incorrecto = pend.codigo === '0000' ? '1111' : '0000';
      procesarMensaje(estado, msj(999, { text: incorrecto }), ALLOWED, OWNER, momento + 1);
    }
    momento += 3;
  }
  assert.ok(estado.bloqueados['999'], 'debió bloquear antes de 20 ciclos');
  assert.ok(ciclos < 20);

  // Código vencido → no aprueba, pide reiniciar con /start.
  estado = estadoVacio();
  estado.pendientes['999'] = { codigo: '1234', vence: 500 };
  r = procesarMensaje(estado, msj(999, { text: '1234' }), ALLOWED, OWNER, 1000);
  assert.ok(r.resultados[0].texto.includes('venció'));
  assert.ok(!estado.pendientes['999']);
  assert.ok(!estado.aprobados.includes('999'));

  // Dueño: /quitar <id> saca a alguien de aprobados.
  estado = estadoVacio();
  estado.aprobados.push('777');
  r = procesarMensaje(estado, msj(Number(OWNER), { text: '/quitar 777' }), ALLOWED, OWNER, 1000);
  assert.ok(r.resultados[0].texto.includes('Quitado'));
  assert.ok(!estado.aprobados.includes('777'));

  // No-dueño usando /quitar → se ignora, no se quita a nadie.
  estado = estadoVacio();
  estado.aprobados.push('777');
  r = procesarMensaje(estado, msj(999, { text: '/quitar 777' }), ALLOWED, OWNER, 1000);
  assert.strictEqual(r.resultados[0].accion, 'ignorar');
  assert.ok(estado.aprobados.includes('777'));

  console.log('OK: validar_mensaje.js — 28 casos pasaron');
}

if (typeof require !== 'undefined' && require.main === module) {
  demo();
}

// Arma el mensaje de confirmación con el link real al post recién
// publicado (usa el message_id que Telegram acaba de devolver, y el
// chatId del remitente original que mandó la foto, no el del canal).
// Si el análisis de imagen con IA cayó a fallback (modelo caído, tardó
// más de 60s, o JSON inválido) se publicó igual con el caption ORIGINAL
// (ver motor_caption.js) -- aquí solo se avisa al dueño de que pasó.
const resp = $input.first().json;
const chatId = $('Validar mensaje').first().json.chatId;
if (!resp.ok) {
  return [{ json: { chatId, texto: 'No se pudo publicar en el canal: ' + (resp.description || 'error desconocido') } }];
}
const messageId = resp.result.message_id;
const link = `https://t.me/${$env.TELEGRAM_CHANNEL_USERNAME}/${messageId}`;
const salidas = [{ json: { chatId, texto: `Publicado en el canal: ${link}` } }];
const armado = $('Armar caption').first().json;
if (armado.fallback) {
  salidas.push({
    json: {
      chatId: $env.TELEGRAM_OWNER_ID,
      texto: `Aviso: no se pudo analizar la imagen con IA (${armado.motivo}); se publicó el caption original tal cual.`,
    },
  });
}
return salidas;

// Convierte la imagen descargada (binary) a base64 para mandarla al
// modelo de visión. Si "Descargar imagen" falló (onError:
// continueRegularOutput), no hay binary: se manda null y "Armar
// caption" cae a fallback (publica el caption original).
const bin = $input.first().binary;
return [{ json: { imagenBase64: bin && bin.data ? bin.data.data : null } }];

// Lógica pura del nodo "Armar caption" del workflow "Afiliados - Publicar en
// Telegram". Testeable con `node workflows/src/motor_caption.js` por fuera de
// n8n. El Code node del workflow pega este archivo tal cual (función +
// bloque de invocación con $input/$env de abajo), mismo patrón que
// validar_mensaje.js.
//
// Entra aquí DESPUÉS de "Analizar imagen" (HTTP Request a Ollama local, el
// mismo proveedor que usa lemut_n8n para el LLM que lee documentos — ver
// README). La respuesta del modelo es texto libre que DEBERÍA ser un JSON
// (Ollama con `temperature:0`, sin `format` forzado porque el endpoint es el
// OpenAI-compatible /v1/chat/completions); se valida y arma el caption con
// una plantilla fija en código (el LLM NO redacta texto, solo extrae datos).
//
// Regla dura del negocio: si el modelo falla, tarda, o el JSON es inválido/
// incompleto, se cae a fallback = se publica el caption ORIGINAL que mandó
// el afiliado (nunca se bloquea la publicación por un problema del LLM).

const LIMITE_CAPTION = 1024; // mismo límite que validar_mensaje.js (caption de foto en Telegram).

// Defensa en profundidad: el único link que debe salir en el caption es
// original.link (el que mandó el afiliado); ningún campo que devuelva el
// LLM (nombre, tienda, promociones...) debe poder colar un link distinto.
// Genérica a propósito: no solo http(s):// ni solo meli.la/
// mercadolibre.com.mx, también dominio.tld(/ruta) sin esquema (bit.ly/abc,
// t.me/canal, www.otro.com...). El TLD final debe ser solo letras (2+)
// para no atrapar precios/decimales ("13,229.02"). Misma regex que
// validar_mensaje.js/motor_cupones.js (duplicada: cada Code node de n8n es
// autocontenido).
const URL_GENERICA_RE = /https?:\/\/\S+|\b[\w-]+(?:\.[\w-]+)*\.[a-z]{2,}(?:\/\S*)?\b/gi;
function quitarLinks(texto) {
  return String(texto || '')
    .replace(URL_GENERICA_RE, '')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Solo string/number se tratan como texto; cualquier otro tipo (objeto,
// array...) que el LLM devuelva en un campo de texto se descarta como ''
// en vez de colarse via String() como "[object Object]" (reportado en
// revisión).
function aTextoSeguro(valor) {
  if (typeof valor === 'string') return valor;
  if (typeof valor === 'number' && Number.isFinite(valor)) return String(valor);
  return '';
}

// El modelo a veces envuelve el JSON en fences de markdown pese a la
// instrucción de no hacerlo (típico en modelos chicos) — se despoja antes
// de intentar JSON.parse.
function limpiarRespuesta(texto) {
  if (typeof texto !== 'string') return '';
  return texto.trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
}

function parsearDatos(texto) {
  const limpio = limpiarRespuesta(texto);
  if (!limpio) return null;
  try {
    const datos = JSON.parse(limpio);
    if (!datos || typeof datos !== 'object' || Array.isArray(datos)) return null;
    return datos;
  } catch (e) {
    return null;
  }
}

// El modelo a veces agrega texto suelto alrededor del número ("13,039.02 con
// Cupón" en vez de solo "13039.02") pese a la instrucción de mandar solo el
// número — se limpia aquí en vez de pedir un tercer intento de prompt.
// Devuelve un number o null (nunca inventa: si no hay dígitos, no hay monto).
function parsearMonto(valor) {
  if (valor === null || valor === undefined) return null;
  const limpio = String(valor).replace(/[^\d.,]/g, '').replace(/,/g, '');
  if (!limpio) return null;
  const n = parseFloat(limpio);
  return Number.isFinite(n) ? n : null;
}

// Formato mexicano: separador de miles con coma, sin decimales si el monto
// es entero (ej. "$190" en vez de "$190.00").
function formatearMonto(n) {
  const esEntero = Number.isInteger(n);
  const [entero, decimales] = n.toFixed(esEntero ? 0 : 2).split('.');
  const conComas = entero.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return decimales ? `${conComas}.${decimales}` : conComas;
}

// Arma la línea de precio: varias combinaciones según qué haya visto el
// modelo (nunca inventa "antes"/"%" si no vienen de la imagen). Cada precio
// se valida con parsearMonto (formato numérico) antes de mostrarlo — el
// LLM nunca interpola texto libre suyo aquí, solo números ya verificados
// (defensa BAJA pedida por el revisor: así un precio con basura/un link
// alrededor nunca se publica tal cual).
function lineaPrecio(datos) {
  const actual = parsearMonto(datos.precio_actual);
  if (actual === null) return null;
  const anterior = parsearMonto(datos.precio_anterior);
  const descuento = parsearMonto(datos.descuento_pct);
  if (anterior !== null) {
    let linea = `💲 Ahora $${formatearMonto(actual)} (antes $${formatearMonto(anterior)}`;
    if (descuento !== null) linea += `, -${formatearMonto(descuento)}%`;
    return linea + ')';
  }
  if (descuento !== null) return `💲 $${formatearMonto(actual)} (-${formatearMonto(descuento)}%)`;
  return `💲 $${formatearMonto(actual)}`;
}

// El ahorro se calcula aquí (en código), nunca lo redacta el modelo: si
// precio_actual y precio_con_cupon son números válidos y el cupón sí baja el
// precio, arma "de $X a $Y (ahorras $Z)"; si no se puede calcular (falta el
// precio_actual o el cupón no baja el precio), cae a la forma simple.
function lineaCupon(datos) {
  const conCupon = parsearMonto(datos.precio_con_cupon);
  if (conCupon !== null) {
    const actual = parsearMonto(datos.precio_actual);
    if (actual !== null && actual > conCupon) {
      const ahorro = Math.round((actual - conCupon) * 100) / 100;
      return `🎟️ Con cupón: de $${formatearMonto(actual)} a $${formatearMonto(conCupon)} (ahorras $${formatearMonto(ahorro)})`;
    }
    return `🎟️ Con cupón: $${formatearMonto(conCupon)}`;
  }
  if (datos.cupon_disponible) return '🎟️ Tiene cupón disponible';
  return null;
}

// Meli Dólar es la stablecoin 1:1 con el dólar de Mercado Pago (ver
// Términos y condiciones de Ripio / Meli Dólar): el cashback solo se
// acredita pagando con Tarjeta de Crédito Mercado Pago siendo Meli+ — se
// deja explícito en la línea para que no se confunda con pesos ni con un
// descuento directo. Monto con 2 decimales, sin signo $ (es dólares, no
// pesos).
function lineaCashback(datos) {
  const monto = parsearMonto(datos.cashback_monto);
  if (monto === null) return null;
  return `💰 ${monto.toFixed(2)} dólares de cashback en Meli Dólar (con Meli+ y Tarjeta de Crédito Mercado Pago)`;
}

// El modelo a veces devuelve el renglón completo del banner ("Visita la
// Tienda oficial de Samsung") en vez de solo el nombre — se recorta el
// prefijo conocido, sin inventar ni cambiar el nombre que sí reportó.
function limpiarTienda(valorCrudo) {
  const valor = aTextoSeguro(valorCrudo);
  if (!valor) return null;
  const limpio = quitarLinks(valor.replace(/^\s*visita\s+la\s+tienda\s+oficial\s+de\s*/i, ''));
  return limpio || null;
}

// El modelo a veces pierde las comillas de pulgadas en nombre_corto (las
// cambia por un espacio: "70 4K" en vez de "70\" 4K") aunque sí las ponga
// en nombre_completo. Se agrega aquí, en código, SOLO si el número ya
// aparece tal cual en nombre_corto (nunca inventa un tamaño que el modelo
// no haya reportado ahí).
function normalizarPulgadas(nombreCorto, nombreCompleto) {
  if (!nombreCorto || !nombreCompleto) return nombreCorto;
  const conComillas = /(\d+)\s*"/.exec(nombreCompleto);
  if (!conComillas) return nombreCorto;
  const numero = conComillas[1];
  if (new RegExp(`${numero}\\s*"`).test(nombreCorto)) return nombreCorto; // ya las tiene.
  const sinComillas = new RegExp(`\\b${numero}\\b(?!\\s*")`);
  if (!sinComillas.test(nombreCorto)) return nombreCorto; // el número ni aparece, no tocar.
  return nombreCorto.replace(sinComillas, `${numero}"`);
}

function fallback(motivo, original) {
  return { caption: String((original && original.caption) || ''), fallback: true, motivo };
}

// original: { caption, link, textoUsuario } — vienen de "Validar mensaje"
// (ver validar_mensaje.js). respuestaModelo: el texto crudo que mandó el LLM
// (o undefined/null si la llamada falló o se cayó por timeout). Todo el
// cuerpo va en try/catch: el LLM puede devolver tipos inesperados (número o
// array donde se esperaba string) y aunque cada campo se normaliza con
// String()/Array.isArray(), cualquier caso no previsto cae a fallback en
// vez de tirar el Code node completo (reportado MEDIA por el revisor).
function armarCaption(respuestaModelo, original) {
  try {
    if (!original || !original.link) return fallback('sin_link_original', original || {});

    const datos = parsearDatos(respuestaModelo);
    if (!datos) return fallback('json_invalido', original);

    let nombre = quitarLinks((aTextoSeguro(datos.nombre_corto) || aTextoSeguro(datos.nombre_completo)).trim());
    nombre = normalizarPulgadas(nombre, aTextoSeguro(datos.nombre_completo));
    if (!nombre) return fallback('sin_nombre_producto', original);

    const tienda = limpiarTienda(datos.tienda_oficial);
    const promos = Array.isArray(datos.promociones)
      ? datos.promociones.filter((x) => typeof x === 'string' && x.trim()).map((x) => quitarLinks(x)).filter(Boolean)
      : [];
    const encabezado = [
      `🔥 ¡Ofertota! ${nombre}`,
      lineaPrecio(datos),
      lineaCupon(datos),
      lineaCashback(datos),
      promos.length ? `✅ ${promos.join(' · ')}` : null,
      tienda ? `🏬 Tienda oficial ${tienda}` : null,
    ].filter(Boolean).join('\n');

    const bloques = [encabezado];

    const nombreCompleto = quitarLinks(aTextoSeguro(datos.nombre_completo).trim());
    if (nombreCompleto && nombreCompleto !== nombre) bloques.push(nombreCompleto);

    const textoUsuario = String(original.textoUsuario || '').trim();
    if (textoUsuario) bloques.push(textoUsuario);

    bloques.push(`👉 Cómpralo aquí: ${original.link}`);

    const caption = bloques.join('\n\n');
    if (caption.length > LIMITE_CAPTION) return fallback('caption_muy_largo', original);

    return { caption, fallback: false, motivo: null };
  } catch (e) {
    return fallback('error_inesperado', original || {});
  }
}

if (typeof module !== 'undefined') {
  module.exports = { armarCaption, parsearDatos, parsearMonto, formatearMonto, quitarLinks, aTextoSeguro, LIMITE_CAPTION };
}

// --- Bloque de invocación dentro de n8n (Code node "Armar caption") ---
// Fuera de n8n, $input/$env no existen y este bloque no corre (ver demo()).
if (typeof $input !== 'undefined') {
  // Salida de "Analizar imagen" (HTTP Request, formato OpenAI-compatible de
  // Ollama): éxito → { choices: [{ message: { content: "<json>" } }] };
  // si falló o tardó más de 120s, "onError: continueRegularOutput" deja un
  // objeto con `.error` en vez de `.choices` (no revienta el workflow).
  const respuesta = $input.first().json;
  const textoModelo = respuesta && respuesta.choices && respuesta.choices[0]
    ? respuesta.choices[0].message?.content
    : null;

  const original = $('Validar mensaje').first().json; // { chatId, fileId, caption, link, textoUsuario }
  // try/catch extra (defensa en profundidad): armarCaption ya no debería
  // tirar nunca, pero si algo fuera de su try/catch interno fallara (ej.
  // original con forma rara), igual cae a fallback en vez de reventar el nodo.
  let resultado;
  try {
    resultado = armarCaption(textoModelo, original);
  } catch (e) {
    resultado = { caption: String(original.caption || ''), fallback: true, motivo: 'error_inesperado_nodo' };
  }

  return [{
    json: {
      accion: 'publicar',
      chatId: original.chatId,
      fileId: original.fileId,
      caption: resultado.caption,
      fallback: resultado.fallback,
      motivo: resultado.motivo,
    },
  }];
}

// --- Self-check mínimo (node workflows/src/motor_caption.js) ---
// Datos 100% sintéticos (repo público): ningún precio/cupón real de Mercado
// Libre, solo valores de prueba.
function demo() {
  const assert = require('assert');
  const original = (extra) => ({
    caption: 'Oferta https://meli.la/abc123',
    link: 'https://meli.la/abc123',
    textoUsuario: 'Oferta',
    ...extra,
  });

  // Todo completo: cupón con ahorro calculado en código, cashback, tienda
  // limpiada del renglón completo del banner, promociones.
  let r = armarCaption(JSON.stringify({
    nombre_corto: 'Bocina X100',
    nombre_completo: 'Bocina Bluetooth X100 Pro 20W Resistente al Agua',
    marca: 'MarcaDemo',
    precio_actual: '1,500.00',
    precio_anterior: null,
    descuento_pct: null,
    precio_con_cupon: '1300',
    cupon_disponible: true,
    cashback_monto: '20.50',
    promociones: ['3 meses sin intereses', 'Envío gratis'],
    tienda_oficial: 'Visita la Tienda oficial de MarcaDemo',
  }), original());
  assert.strictEqual(r.fallback, false);
  assert.ok(r.caption.includes('🔥 ¡Ofertota! Bocina X100'));
  assert.ok(r.caption.includes('💲 $1,500'));
  assert.ok(r.caption.includes('🎟️ Con cupón: de $1,500 a $1,300 (ahorras $200)'));
  assert.ok(r.caption.includes('💰 20.50 dólares de cashback en Meli Dólar (con Meli+ y Tarjeta de Crédito Mercado Pago)'));
  assert.ok(r.caption.includes('3 meses sin intereses · Envío gratis'));
  assert.ok(r.caption.includes('🏬 Tienda oficial MarcaDemo')); // sin el "Visita la Tienda oficial de".
  assert.ok(r.caption.includes('Bocina Bluetooth X100 Pro 20W Resistente al Agua'));
  assert.ok(r.caption.includes('Oferta')); // texto del usuario.
  assert.ok(r.caption.endsWith('👉 Cómpralo aquí: https://meli.la/abc123'));

  // Cupón disponible pero SIN poder leer el precio con cupón.
  r = armarCaption(JSON.stringify({
    nombre_corto: 'Bocina X100',
    precio_actual: '999',
    precio_con_cupon: null,
    cupon_disponible: true,
    promociones: [],
  }), original());
  assert.ok(r.caption.includes('🎟️ Tiene cupón disponible'));

  // Sin cupón ni cashback en absoluto.
  r = armarCaption(JSON.stringify({
    nombre_corto: 'Bocina X100',
    nombre_completo: null,
    precio_actual: '999',
    precio_anterior: null,
    descuento_pct: null,
    precio_con_cupon: null,
    cupon_disponible: false,
    cashback_monto: null,
    promociones: [],
    tienda_oficial: null,
  }), original());
  assert.strictEqual(r.fallback, false);
  assert.ok(!r.caption.includes('Cupón') && !r.caption.includes('cupón'));
  assert.ok(!r.caption.includes('cashback'));

  // precio_con_cupon con texto suelto alrededor (lo que de verdad manda el
  // modelo a veces, ej. "13,039.02 con Cupón") -- se limpia solo, sin
  // necesitar reintentar el prompt.
  r = armarCaption(JSON.stringify({
    nombre_corto: 'TV Demo',
    precio_actual: '13,229.02',
    precio_con_cupon: '13,039.02 con Cupón',
  }), original());
  assert.ok(r.caption.includes('🎟️ Con cupón: de $13,229.02 a $13,039.02 (ahorras $190)'));

  // Cashback con monto entero: siempre 2 decimales ("15.00", no "15").
  r = armarCaption(JSON.stringify({
    nombre_corto: 'Bocina X100',
    precio_actual: '999',
    cashback_monto: '15',
  }), original());
  assert.ok(r.caption.includes('💰 15.00 dólares de cashback en Meli Dólar (con Meli+ y Tarjeta de Crédito Mercado Pago)'));

  // nombre_corto sin comillas de pulgadas pero nombre_completo sí las
  // trae, y el número SÍ aparece en nombre_corto → se agregan las
  // comillas (normalizarPulgadas), nunca lo deja el LLM.
  r = armarCaption(JSON.stringify({
    nombre_corto: 'TV Samsung 70 4K',
    nombre_completo: 'Samsung Pantalla 70" Crystal UHD 4K Smart TV',
    precio_actual: '999',
  }), original());
  assert.ok(r.caption.includes('TV Samsung 70" 4K'));

  // nombre_corto ya trae las comillas → no se duplican.
  r = armarCaption(JSON.stringify({
    nombre_corto: 'TV Samsung 70" 4K',
    nombre_completo: 'Samsung Pantalla 70" Crystal UHD 4K Smart TV',
    precio_actual: '999',
  }), original());
  assert.ok(r.caption.includes('TV Samsung 70" 4K'));
  assert.ok(!r.caption.includes('70"" 4K'));

  // El número de pulgadas NO aparece en nombre_corto (otro tamaño, u otro
  // dato) → no se inventa nada; el encabezado (línea "¡Ofertota!") se deja
  // tal cual lo mandó el modelo, aunque nombre_completo sí traiga "70\"".
  r = armarCaption(JSON.stringify({
    nombre_corto: 'Smart TV 4K',
    nombre_completo: 'Samsung Pantalla 70" Crystal UHD 4K Smart TV',
    precio_actual: '999',
  }), original());
  const encabezadoLinea = r.caption.split('\n')[0];
  assert.strictEqual(encabezadoLinea, '🔥 ¡Ofertota! Smart TV 4K');

  // Sin precio anterior (no debe decir "Ahora" ni dejar paréntesis vacíos).
  r = armarCaption(JSON.stringify({
    nombre_corto: 'Bocina X100',
    precio_actual: '999',
    precio_anterior: null,
    descuento_pct: null,
    promociones: [],
    tienda_oficial: null,
  }), original());
  assert.ok(r.caption.includes('💲 $999'));
  assert.ok(!r.caption.includes('Ahora'));
  assert.ok(!r.caption.includes('('));

  // Ningún campo del LLM debe poder colar un link (solo original.link
  // puede salir) — ni en promociones, ni en nombre_completo, ni en tienda,
  // y ni siquiera un link SIN esquema (bit.ly, no solo http(s)://) (bug
  // BAJA reportado por el revisor).
  r = armarCaption(JSON.stringify({
    nombre_corto: 'Bocina X100',
    nombre_completo: 'Bocina X100, detalles en bit.ly/promo',
    precio_actual: '999',
    promociones: ['Envío gratis', 'más info en t.me/canal'],
    tienda_oficial: 'Visita la Tienda oficial de MarcaDemo (www.otro.com)',
  }), original());
  assert.strictEqual(r.fallback, false);
  assert.ok(!r.caption.includes('bit.ly'));
  assert.ok(!r.caption.includes('t.me'));
  assert.ok(!r.caption.includes('www.otro.com'));
  assert.ok(r.caption.includes('👉 Cómpralo aquí: https://meli.la/abc123')); // el único link permitido.

  // precio_actual con basura/link alrededor (lo que de verdad manda un LLM
  // a veces) → se valida como número (parsearMonto), nunca se interpola
  // texto libre ni se cuela un link por ese campo.
  r = armarCaption(JSON.stringify({
    nombre_corto: 'Bocina X100',
    precio_actual: '999 (ver http://evil.com)',
  }), original());
  assert.ok(r.caption.includes('💲 $999'));
  assert.ok(!r.caption.includes('evil.com'));

  // Tipos inesperados del LLM (number donde se esperaba string, o un array
  // donde se esperaba lista de strings) no deben tirar el motor: antes,
  // `(datos.nombre_corto || ...).trim()` con un number lanzaba TypeError;
  // ahora se coacciona con String() y, aunque no fuera así, el try/catch
  // cae a fallback.
  r = armarCaption(JSON.stringify({
    nombre_corto: 2026,
    precio_actual: 999,
    descuento_pct: 10,
    promociones: 'no es una lista',
  }), original());
  assert.strictEqual(r.fallback, false);
  assert.ok(r.caption.includes('🔥 ¡Ofertota! 2026'));
  assert.ok(r.caption.includes('💲 $999 (-10%)'));

  // Tipo que NO es string/number (objeto) en nombre_corto → se trata como
  // vacío (aTextoSeguro) y cae al siguiente campo disponible
  // (nombre_completo), nunca se publica "[object Object]" (bug detectado
  // en revisión: String(obj) sí lo filtraba, pero no debía aceptarlo).
  r = armarCaption(JSON.stringify({
    nombre_corto: { raro: true },
    nombre_completo: 'Bocina X100 Pro',
    precio_actual: '999',
  }), original());
  assert.strictEqual(r.fallback, false);
  assert.ok(!r.caption.includes('[object Object]'));
  assert.ok(r.caption.includes('🔥 ¡Ofertota! Bocina X100 Pro'));

  // Error inesperado no previsto (ej. original con una propiedad que
  // truena al leerla) → el try/catch de armarCaption cae a fallback en vez
  // de tirar el Code node completo (defensa en profundidad pedida por el
  // revisor, más allá de las normalizaciones puntuales de arriba).
  const originalRaro = {
    caption: 'orig', link: 'https://meli.la/abc123',
    get textoUsuario() { throw new Error('boom'); },
  };
  r = armarCaption(JSON.stringify({ nombre_corto: 'Bocina X100', precio_actual: '999' }), originalRaro);
  assert.strictEqual(r.fallback, true);
  assert.strictEqual(r.motivo, 'error_inesperado');
  assert.strictEqual(r.caption, 'orig');

  // JSON inválido → fallback al caption original.
  r = armarCaption('esto no es json', original());
  assert.strictEqual(r.fallback, true);
  assert.strictEqual(r.motivo, 'json_invalido');
  assert.strictEqual(r.caption, 'Oferta https://meli.la/abc123');

  // Respuesta vacía/null (timeout o error de red) → fallback.
  r = armarCaption(null, original());
  assert.strictEqual(r.fallback, true);

  // JSON envuelto en fences de markdown → se limpia y parsea igual.
  r = armarCaption('```json\n{"nombre_corto":"Bocina X100","precio_actual":"999"}\n```', original());
  assert.strictEqual(r.fallback, false);

  // nombre_corto y nombre_completo ambos null → no hay nombre, fallback.
  r = armarCaption(JSON.stringify({ nombre_corto: null, nombre_completo: null, precio_actual: '999' }), original());
  assert.strictEqual(r.fallback, true);
  assert.strictEqual(r.motivo, 'sin_nombre_producto');

  // Caption resultante > 1024 (promociones/nombre larguísimos) → fallback,
  // no se rechaza la publicación, se publica el original.
  r = armarCaption(JSON.stringify({
    nombre_corto: 'Producto',
    nombre_completo: 'N'.repeat(500),
    promociones: ['P'.repeat(600)],
    precio_actual: '999',
  }), original());
  assert.strictEqual(r.fallback, true);
  assert.strictEqual(r.motivo, 'caption_muy_largo');

  console.log('OK: motor_caption.js — 19 casos pasaron');
}

